import json, sys
data = json.loads(sys.stdin.read())
registry = json.loads(data['result'])
exps = registry['data']['experiments']

# Get all eval metrics with success rates
eval_exps = {}
for k, e in exps.items():
    if 'eval' in k and ('vanilla' in k or 'taxei' in k or 'random' in k) and 'recovery' not in k and 'fixed' not in k:
        m = e.get('metrics', {}) or {}
        sr = m.get('success_rate')
        if sr is None:
            # Try nested
            sr = m.get('successes')
            total = m.get('total')
            if sr is not None and total:
                sr = sr / total
        eval_exps[k] = {
            'status': e['status'],
            'conclusion': e.get('conclusion'),
            'success_rate': sr,
            'metrics': m
        }

# Print organized by method and seed
methods = ['vanilla', 'taxei', 'random']
seeds = ['42', '0', '123', '1', '7']

print('5-Seed Eval Progress Table:')
print(f'{\"Method\":<12} {\"seed=42\":<12} {\"seed=0\":<12} {\"seed=123\":<12} {\"seed=1\":<12} {\"seed=7\":<12}')
print('-' * 72)

for method in methods:
    row = f'{method:<12}'
    for seed in seeds:
        if seed == '42':
            key = f'v4-{method}-eval'
        else:
            key = f'v4-{method}-seed{seed}-eval'

        if key in eval_exps:
            e = eval_exps[key]
            sr = e['success_rate']
            status = e['status']
            if sr is not None:
                cell = f'{sr:.1%}'
            elif status == 'RUNNING':
                cell = 'RUNNING'
            elif status == 'DONE':
                cell = f'DONE({e[\"conclusion\"]})'
            else:
                cell = status
        else:
            key_check = [k for k in eval_exps if method in k and f'seed{seed}' in k]
            if key_check:
                cell = 'EXISTS'
            else:
                cell = '—'
        row += f' {cell:<12}'
    print(row)

# Print detailed metrics
print()
print('=== Detailed Eval Metrics ===')
for k in sorted(eval_exps.keys()):
    e = eval_exps[k]
    if e['metrics']:
        print(f'{k}: {json.dumps(e[\"metrics\"], indent=None)[:200]}')
